/** A house of the row by its OpenStreetMap id */
export const houseById = (id) => MATTASTRASSE_2.houses.find((h) => h.id === id);
/** The outlines the player's walls stand on (js/landmarks.js SURVEYED_FOOTPRINTS) */
export const groundOutlines = (h) => h.rings;
/** Is a point inside any house of the row (at the ground)? */
export const insideRow = (x, z) => MATTASTRASSE_2.houses.some((h) => h.rings.some((r) => pointInRing(r, x, z)));
/** A wall's frame (wallFrame: s along it from `a`, its outside on n) */
export const frameOf = (w) => wallFrame(w.a, w.b);
/** A wall's triangles: [[s, y] × 3] */
export const wallTriangles = (w) => {
  const out = [];
  for (let i = 0; i + 5 < w.t.length; i += 6) out.push([[w.t[i], w.t[i + 1]], [w.t[i + 2], w.t[i + 3]], [w.t[i + 4], w.t[i + 5]]]);
  return out;
};
/** The roof's triangles: [[x, y, z] × 3] */
export const roofTriangles = (h) => h.roof.map((t) => [[t[0], t[1], t[2]], [t[3], t[4], t[5]], [t[6], t[7], t[8]]]);

/** Where the vertical line at s crosses a wall's triangles: [lowest, highest] y, or null */
export function spanAt(tris, s) {
  let lo = Infinity, hi = -Infinity;
  for (const T of tris) {
    for (let i = 0; i < 3; i++) {
      const p = T[i], q = T[(i + 1) % 3];
      const a = Math.min(p[0], q[0]), b = Math.max(p[0], q[0]);
      if (s < a - 1e-6 || s > b + 1e-6) continue;
      const y = b - a < 1e-6 ? null : p[1] + ((s - p[0]) * (q[1] - p[1])) / (q[0] - p[0]);
      for (const v of y === null ? [p[1], q[1]] : [y]) { lo = Math.min(lo, v); hi = Math.max(hi, v); }
    }
  }
  return lo <= hi ? [lo, hi] : null;
}
/** A wall's measures: its length, its eaves (the lowest top), its highest top, its foot (sampled along it) */
export function wallMeasures(w) {
  const F = frameOf(w), tris = wallTriangles(w);
  let minTop = Infinity, maxTop = -Infinity, foot = Infinity;
  const n = Math.max(4, Math.ceil(F.len / 0.5));
  for (let k = 0; k <= n; k++) {
    const sp = spanAt(tris, 0.05 + ((F.len - 0.1) * k) / n);
    if (!sp) continue;
    minTop = Math.min(minTop, sp[1]); maxTop = Math.max(maxTop, sp[1]); foot = Math.min(foot, sp[0]);
  }
  return { F, tris, len: F.len, minTop, maxTop, foot };
}
/** The part of a polygon ([[s, y], …]) between heights lo and hi */
export function clipBand(poly, lo, hi) {
  const cut = (pts, keep, at) => {
    const out = [];
    for (let i = 0; i < pts.length; i++) {
      const p = pts[i], q = pts[(i + 1) % pts.length], kp = keep(p), kq = keep(q);
      if (kp) out.push(p);
      if (kp !== kq) { const t = (at - p[1]) / (q[1] - p[1]); out.push([p[0] + (q[0] - p[0]) * t, at]); }
    }
    return out;
  };
  let pts = cut(poly, (p) => p[1] >= lo, lo);
  if (pts.length >= 3) pts = cut(pts, (p) => p[1] <= hi, hi);
  return pts.length >= 3 ? pts : [];
}
/** The heights of a house's roof over a point, or [] */
export function roofHeights(h, x, z) {
  const out = [];
  for (const t of h.roof) {
    const d = (t[5] - t[8]) * (t[0] - t[6]) + (t[6] - t[3]) * (t[2] - t[8]);
    if (Math.abs(d) < 1e-9) continue;
    const l1 = ((t[5] - t[8]) * (x - t[6]) + (t[6] - t[3]) * (z - t[8])) / d;
    const l2 = ((t[8] - t[2]) * (x - t[6]) + (t[0] - t[6]) * (z - t[8])) / d;
    const l3 = 1 - l1 - l2;
    if (l1 < -1e-4 || l2 < -1e-4 || l3 < -1e-4) continue;
    out.push(l1 * t[1] + l2 * t[4] + l3 * t[7]);
  }
  return out;
}
/** The free edges of a house's roof (used by one triangle only): [[x, y, z], [x, y, z], the triangle's middle] */
export function roofEdges(h) {
  const key = (p) => `${p[0].toFixed(1)},${p[2].toFixed(1)}`;
  const count = new Map(), edges = [];
  for (const T of roofTriangles(h)) {
    const m = [(T[0][0] + T[1][0] + T[2][0]) / 3, (T[0][1] + T[1][1] + T[2][1]) / 3, (T[0][2] + T[1][2] + T[2][2]) / 3];
    for (let i = 0; i < 3; i++) {
      const p = T[i], q = T[(i + 1) % 3], a = key(p), b = key(q);
      if (a === b) continue;
      const k = a < b ? a + '|' + b : b + '|' + a;
      count.set(k, (count.get(k) || 0) + 1);
      edges.push([k, p, q, m]);
    }
  }
  return edges.filter(([k]) => count.get(k) === 1).map(([, p, q, m]) => [p, q, m]);
}

